        for i in range(dim):
            if rng.rand() < mut_rate:
                mutated[i] += (rng.uniform(-1, 1) - 0.5)
        return mutated

    def crossover(parent1, parent2, cr):
        child = parent1.copy()
        for i in range(dim):
            if rng.rand() < cr:
                child[i] = parent2[i]
        return child

    best = np.zeros(dim)
    std_dev = 10.0
    mut_rate = 0.01
    cr = 0.5

